#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [ElectricSurfaceChargeDensity; 3] = [
        ElectricSurfaceChargeDensity::const_new(
            1234.5,
            ElectricSurfaceChargeDensityUnit::CoulombPerSquareMeter,
        ),
        ElectricSurfaceChargeDensity::const_new(
            1234.5,
            ElectricSurfaceChargeDensityUnit::CoulombPerSquareCentimeter,
        ),
        ElectricSurfaceChargeDensity::const_new(
            1234.5,
            ElectricSurfaceChargeDensityUnit::CoulombPerSquareInch,
        ),
    ];
    for (q, &unit) in AT_COMPILE_TIME
        .iter()
        .zip(ElectricSurfaceChargeDensityUnit::ALL)
    {
        assert_eq!(
            q.as_base().to_bits(),
            ElectricSurfaceChargeDensity::new(1234.5_f64, unit)
                .as_base()
                .to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in ElectricSurfaceChargeDensityUnit::ALL {
            assert_eq!(
                ElectricSurfaceChargeDensity::const_new(v, unit)
                    .as_base()
                    .to_bits(),
                ElectricSurfaceChargeDensity::<f64>::new(v, unit)
                    .as_base()
                    .to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = ElectricSurfaceChargeDensity::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            ElectricSurfaceChargeDensity::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in ElectricSurfaceChargeDensityUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        ElectricSurfaceChargeDensity::from_base(0.0)
            .auto_unit()
            .unit,
        ElectricSurfaceChargeDensityUnit::CoulombPerSquareMeter
    );
}

